command:
$ErrorActionPreference = "Stop"
git fetch origin main work/content-encodings --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "3c271accc127e8ff6a4cc120d6c055d7bc97bece") { throw "main moved" }
if ((git rev-parse origin/work/content-encodings).Trim() -ne "bdb40c98fc1d40cae02300cc0ad2d3ee149b0212") { throw "candidate moved" }

git checkout work/content-encodings
if ($LASTEXITCODE -ne 0) { throw "checkout candidate failed" }
git merge --ff-only origin/work/content-encodings
if ($LASTEXITCODE -ne 0) { throw "candidate fast-forward failed" }

if (-not (Test-Path "out\winui\Release\flyExplorer.exe")) { throw "validated candidate Release binary missing" }
if (-not (Test-Path "logs\capture-content-encoding-visual.py")) { throw "encoding visual helper missing" }

python -X utf8 "logs\capture-content-encoding-visual.py" "logs\remote-evidence\content-encoding-after-default.png"
if ($LASTEXITCODE -ne 0) { throw "default encoding visual capture failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }

Write-Host "CONTENT_ENCODING_DEFAULT_VISUAL_PASS"
